{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured with versioning, which can lead to data loss in case of accidental deletion or overwrite."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured with server-side encryption by default using a KMS key, leaving the data at rest unencrypted or encrypted with a less secure method."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured, which can lead to unintended public access to the bucket."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have access logging enabled, making it difficult to track and monitor access to the bucket."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_versioning" "financials_versioning" {
  bucket = aws_s3_bucket.financials.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "financials_encryption" {
  bucket = aws_s3_bucket.financials.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.financials.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_kms_key" "financials" {
  description             = "KMS key for financials bucket"
  deletion_window_in_days = 7
}

resource "aws_s3_bucket_public_access_block" "financials_public_access_block" {
  bucket = aws_s3_bucket.financials.id

  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "financials_logging" {
  bucket = aws_s3_bucket.financials.id

  target_bucket = "${local.resource_prefix.value}-financials-logs"
  target_prefix = "/"
}",
  "fix_summary": "Enabled versioning, server-side encryption with KMS, public access block, and access logging for the S3 bucket."
}
